const $=s=>document.querySelector(s),fmt=n=>new Intl.NumberFormat('en-IN').format(n),money=n=>'₹'+(n>=1e7?(n/1e7).toFixed(2)+' Cr':n>=1e5?(n/1e5).toFixed(2)+' L':fmt(Math.round(n)));let data=[],filtered=[],page=0,view='summary';const fields=['Year','State','City','Risk_Level'],colors={Low:'#b9ce91',Medium:'#78a27b',High:'#d9b45e',Critical:'#bc7363'};const sum=(a,k)=>a.reduce((s,r)=>s+Number(r[k]||0),0),group=(a,k,metric)=>Object.entries(a.reduce((o,r)=>(o[r[k]]=(o[r[k]]||0)+(metric?Number(r[metric]):1),o),{})).sort((a,b)=>b[1]-a[1]);
function options(k){const selected=$('#'+k).value;const rows=k==='City'&&$('#State').value?data.filter(r=>r.State===$('#State').value):data;$('#'+k).replaceChildren(new Option('All '+({Year:'years',State:'states',City:'cities',Risk_Level:'risk levels'}[k]),''),...[...new Set(rows.map(r=>r[k]))].sort().map(v=>new Option(v,v)));if([...$('#'+k).options].some(o=>o.value===selected))$('#'+k).value=selected;}
function update(){filtered=data.filter(r=>fields.every(k=>!$('#'+k).value||String(r[k])===$('#'+k).value));page=0;$('#record-count').textContent=fmt(filtered.length)+' records';render();}
function render(){const n=filtered.length;$('#kpis').innerHTML=[['Total incidents',fmt(n),'Incident records in selection','◈'],['Financial loss',money(sum(filtered,'Financial_Loss_INR')),'Total recorded financial impact','↗'],['Customers affected',fmt(sum(filtered,'Customers_Affected')),'Sum across selected incidents','♧'],['Average risk score',n?(sum(filtered,'Risk_Score')/n).toFixed(1):'—','Mean of recorded risk scores','◎']].map(([l,v,n,i])=>`<article class="kpi"><span class="kpi-label">${l}</span><span class="kpi-symbol">${i}</span><div class="kpi-value">${v}</div><span class="kpi-note">${n}</span></article>`).join('');drawTrend();drawRisk();bars('#threats',view==='analysis'?'Attack_Method':'Threat_Type');bars('#states',view==='analysis'?'Channel':'State','Financial_Loss_INR');renderTable();}
function drawTrend(){const by=Object.fromEntries(group(filtered,'Date'));const dates=[...new Set(data.map(r=>r.Date.slice(0,7)))].sort();const vals=dates.map(m=>filtered.reduce((s,r)=>s+(r.Date.startsWith(m)?1:0),0));const max=Math.max(...vals,1),W=600,H=185;let line=vals.map((v,i)=>`${40+i*540/Math.max(vals.length-1,1)},${150-v/max*125}`).join(' ');$('#trend').innerHTML=`<svg viewBox="0 0 600 185" role="img" aria-label="Monthly incident counts"><defs><linearGradient id="fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#71a18a" stop-opacity=".23"/><stop offset="1" stop-color="#71a18a" stop-opacity="0"/></linearGradient></defs>${[0,1,2,3].map(i=>`<line x1="40" x2="580" y1="${150-i*42}" y2="${150-i*42}" stroke="#e9eee8" stroke-dasharray="3 4"/><text x="0" y="${154-i*42}" fill="#98a293" font-size="9">${Math.round(max*i/3)}</text>`).join('')}<polygon points="40,150 ${line} 580,150" fill="url(#fill)"/><polyline points="${line}" fill="none" stroke="#488569" stroke-width="2.5"/>${vals.map((v,i)=>`<circle cx="${40+i*540/Math.max(vals.length-1,1)}" cy="${150-v/max*125}" r="3" fill="#488569"><title>${dates[i]}: ${v} incidents</title></circle>`).join('')}${dates.filter((d,i)=>i%Math.max(1,Math.ceil(dates.length/7))===0).map(d=>`<text x="${40+dates.indexOf(d)*540/Math.max(vals.length-1,1)}" y="175" text-anchor="middle" fill="#8e9b8d" font-size="9">${new Date(d+'-01').toLocaleDateString('en',{month:'short',year:'2-digit'})}</text>`).join('')}</svg>`;}
function drawRisk(){let start=0;const risks=['Low','Medium','High','Critical'],segments=risks.map(k=>{const n=filtered.filter(r=>r.Risk_Level===k).length;let end=start+(filtered.length?n/filtered.length*100:0),s=`${colors[k]} ${start}% ${end}%`;start=end;return s;});$('#risk').innerHTML=`<div class="donut-layout"><div class="donut" style="background:${filtered.length?'conic-gradient('+segments.join(',')+')':'#edf0ea'}"><div class="donut-center">${fmt(filtered.length)}<small>total incidents</small></div></div><div class="risk-legend">${risks.map(k=>`<div><i style="background:${colors[k]}"></i>${k}<b>${filtered.length?Math.round(filtered.filter(r=>r.Risk_Level===k).length/filtered.length*100):0}%</b></div>`).join('')}</div></div>`;}
function bars(target,k,m){const g=group(filtered,k,m).slice(0,6),max=Math.max(...g.map(x=>x[1]),1);$(target).innerHTML=g.length?g.map(([name,v])=>`<div class="bar-row"><span>${name}</span><div class="bar-track"><div class="bar-fill" style="width:${v/max*100}%"></div></div><b>${m?money(v):fmt(v)}</b></div>`).join(''):'<p>No incidents match these filters.</p>';}
function results(){let q=$('#search').value.toLowerCase();return filtered.filter(r=>Object.values(r).some(v=>String(v).toLowerCase().includes(q))).sort((a,b)=>b.Date.localeCompare(a.Date));}
function renderTable(){const rs=results(),pages=Math.max(1,Math.ceil(rs.length/12));page=Math.min(page,pages-1);$('#rows').innerHTML=rs.slice(page*12,page*12+12).map(r=>`<tr><td><button data-id="${r.Incident_ID}">${r.Incident_ID} ↗</button><small>${r.Date}</small></td><td>${r.Threat_Type}<small>${r.Channel}</small></td><td>${r.City}<small>${r.State}</small></td><td><span class="pill ${r.Risk_Level}">${r.Risk_Level} · ${r.Risk_Score}</span></td><td>${fmt(r.Financial_Loss_INR)}</td><td>${r.Incident_Status}</td></tr>`).join('')||'<tr><td colspan="6">No matching incidents. Try clearing your search or filters.</td></tr>';$('#page-label').textContent=`${fmt(rs.length)} incidents · Page ${page+1} of ${pages}`;$('#prev').disabled=page===0;$('#next').disabled=page>=pages-1;}
fields.forEach(k=>$('#'+k).addEventListener('change',()=>{if(k==='State')options('City');update();}));$('#reset').onclick=()=>{fields.forEach(k=>$('#'+k).value='');options('City');$('#search').value='';update();};document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{view=b.dataset.view;document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('active',x===b));$('#dashboard').classList.toggle('hidden',!['summary','analysis'].includes(view));$('#explorer').classList.toggle('hidden',view!=='details');$('#about').classList.toggle('hidden',view!=='about');$('#title').textContent={summary:'Risk at a glance.',analysis:'Understand the threat.',details:'Explore every incident.',about:'Behind the research.'}[view];$('#threat-title').textContent=view==='analysis'?'Attack methods':'Threat landscape';$('#state-title').textContent=view==='analysis'?'Financial exposure by channel':'Financial exposure by state';render();});$('#search').oninput=()=>{page=0;renderTable();};$('#prev').onclick=()=>{page--;renderTable();};$('#next').onclick=()=>{page++;renderTable();};$('#rows').onclick=e=>{const id=e.target.dataset.id;if(!id)return;const r=data.find(r=>r.Incident_ID===id);$('#detail-fields').replaceChildren(...Object.entries(r).flatMap(([k,v])=>{let dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=k.replaceAll('_',' ');dd.textContent=v;return[dt,dd];}));$('#detail').showModal();};$('#close').onclick=()=>$('#detail').close();$('#export').onclick=()=>{const rs=view==='details'?results():filtered;if(!rs.length)return;const keys=Object.keys(data[0]),csv=[keys,...rs.map(r=>keys.map(k=>r[k]))].map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download='cyber-risk-incidents.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};fetch('data.json').then(r=>{if(!r.ok)throw Error();return r.json();}).then(d=>{data=d;fields.forEach(options);$('#range').textContent=data[0].Date+' – '+data.at(-1).Date;update();}).catch(()=>{$('#dashboard').textContent='The dataset could not be loaded. Please refresh the page.';});
